export class AudioVisualizer {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private analyser: AnalyserNode | null = null;
  private animFrameId: number | null = null;
  private freqData: Uint8Array<ArrayBuffer> | null = null;
  private timeData: Uint8Array<ArrayBuffer> | null = null;
  private phase: number = 0;
  private isRunning: boolean = false;

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    const context = canvas.getContext('2d');
    if (!context) {
      throw new Error('Failed to acquire 2D canvas context');
    }
    this.ctx = context;

    this.setupResize();
  }

  public setAnalyser(analyser: AnalyserNode | null): void {
    this.analyser = analyser;
    if (this.analyser) {
      const bufferLength = this.analyser.frequencyBinCount;
      this.freqData = new Uint8Array(new ArrayBuffer(bufferLength));
      this.timeData = new Uint8Array(new ArrayBuffer(bufferLength));
    }
  }

  private setupResize(): void {
    const resize = () => {
      const rect = this.canvas.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      this.canvas.width = rect.width * dpr;
      this.canvas.height = rect.height * dpr;
      this.ctx.scale(dpr, dpr);
    };

    window.addEventListener('resize', resize);
    resize();
  }

  public start(): void {
    if (this.isRunning) return;
    this.isRunning = true;
    this.render();
  }

  public stop(): void {
    this.isRunning = false;
    if (this.animFrameId !== null) {
      cancelAnimationFrame(this.animFrameId);
      this.animFrameId = null;
    }
  }

  private render = (): void => {
    if (!this.isRunning) return;

    this.animFrameId = requestAnimationFrame(this.render);

    const rect = this.canvas.getBoundingClientRect();
    const width = rect.width;
    const height = rect.height;

    // Clear with True Black OLED background
    this.ctx.fillStyle = '#08080C';
    this.ctx.fillRect(0, 0, width, height);

    let energy = 0;
    if (this.analyser && this.freqData && this.timeData) {
      this.analyser.getByteFrequencyData(this.freqData);
      this.analyser.getByteTimeDomainData(this.timeData);

      // Calculate total audio energy (0.0 to 1.0)
      let sum = 0;
      for (let i = 0; i < 32; i++) {
        sum += this.freqData[i];
      }
      energy = sum / (32 * 255);
    }

    this.phase += 0.02 + energy * 0.05;

    // Draw multi-layered glowing silky wave ribbons
    this.drawGlowWave(width, height, energy, 1.0, '#6366F1', 0.25, 0);
    this.drawGlowWave(width, height, energy, 0.75, '#06B6D4', 0.35, Math.PI * 0.4);
    this.drawGlowWave(width, height, energy, 0.5, '#10B981', 0.20, Math.PI * 0.8);
    this.drawCenterAura(width, height, energy);
  };

  private drawGlowWave(
    width: number,
    height: number,
    energy: number,
    freqMultiplier: number,
    color: string,
    alpha: number,
    phaseOffset: number
  ): void {
    const midY = height / 2;
    const baseAmp = 6 + energy * 42;

    this.ctx.save();
    this.ctx.beginPath();
    this.ctx.moveTo(0, midY);

    const points = 36;
    const step = width / points;

    for (let i = 0; i <= points; i++) {
      const x = i * step;
      // Combine multiple harmonic sines for smooth organic liquid feel
      const norm = (x / width) * Math.PI * 2;
      const yOffset =
        Math.sin(norm * freqMultiplier + this.phase + phaseOffset) * baseAmp +
        Math.cos(norm * 2.2 - this.phase * 0.6) * (baseAmp * 0.35);

      const y = midY + yOffset;
      if (i === 0) {
        this.ctx.moveTo(x, y);
      } else {
        const prevX = (i - 1) * step;
        const cX = (prevX + x) / 2;
        this.ctx.quadraticCurveTo(prevX, y, cX, y);
      }
    }

    this.ctx.lineTo(width, midY);
    this.ctx.strokeStyle = color;
    this.ctx.lineWidth = 2.0 + energy * 2.5;
    this.ctx.shadowColor = color;
    this.ctx.shadowBlur = 14 + energy * 20;
    this.ctx.globalAlpha = Math.min(1.0, alpha + energy * 0.4);
    this.ctx.stroke();

    this.ctx.restore();
  }

  private drawCenterAura(width: number, height: number, energy: number): void {
    const midX = width / 2;
    const midY = height / 2;
    const radius = 60 + energy * 110;

    const grad = this.ctx.createRadialGradient(midX, midY, 0, midX, midY, radius);
    grad.addColorStop(0, `rgba(99, 102, 241, ${0.08 + energy * 0.18})`);
    grad.addColorStop(0.5, `rgba(6, 182, 212, ${0.04 + energy * 0.10})`);
    grad.addColorStop(1, 'rgba(8, 8, 12, 0)');

    this.ctx.save();
    this.ctx.fillStyle = grad;
    this.ctx.beginPath();
    this.ctx.arc(midX, midY, radius, 0, Math.PI * 2);
    this.ctx.fill();
    this.ctx.restore();
  }
}
