import { BaseProceduralGenerator } from '../SoundGenerator';

/**
 * 12. Binaural Alpha Waves (10 Hz beat difference)
 * Left: 210 Hz, Right: 220 Hz + Warm harmonic drone pad
 */
export class BinauralAlphaGenerator extends BaseProceduralGenerator {
  private oscL: OscillatorNode | null = null;
  private oscR: OscillatorNode | null = null;
  private subOsc: OscillatorNode | null = null;
  private merger: ChannelMergerNode | null = null;

  public startSynthesis(): void {
    const now = this.ctx.currentTime;

    // Carrier & Binaural Split
    this.oscL = this.ctx.createOscillator();
    this.oscR = this.ctx.createOscillator();
    this.subOsc = this.ctx.createOscillator();

    this.oscL.type = 'sine';
    this.oscR.type = 'sine';
    this.subOsc.type = 'triangle';

    this.oscL.frequency.setValueAtTime(210, now);
    this.oscR.frequency.setValueAtTime(220, now); // 10 Hz difference (Alpha)
    this.subOsc.frequency.setValueAtTime(105, now);

    const gainL = this.ctx.createGain();
    const gainR = this.ctx.createGain();
    const gainSub = this.ctx.createGain();

    gainL.gain.setValueAtTime(0.35, now);
    gainR.gain.setValueAtTime(0.35, now);
    gainSub.gain.setValueAtTime(0.12, now);

    this.merger = this.ctx.createChannelMerger(2);

    this.oscL.connect(gainL);
    this.oscR.connect(gainR);
    this.subOsc.connect(gainSub);

    gainL.connect(this.merger, 0, 0); // Left channel
    gainR.connect(this.merger, 0, 1); // Right channel
    gainSub.connect(this.merger, 0, 0);
    gainSub.connect(this.merger, 0, 1);

    this.merger.connect(this.outputGain);

    this.oscL.start();
    this.oscR.start();
    this.subOsc.start();
  }

  public stopSynthesis(): void {
    if (this.oscL) {
      try { this.oscL.stop(); this.oscL.disconnect(); } catch { /* ignore */ }
      this.oscL = null;
    }
    if (this.oscR) {
      try { this.oscR.stop(); this.oscR.disconnect(); } catch { /* ignore */ }
      this.oscR = null;
    }
    if (this.subOsc) {
      try { this.subOsc.stop(); this.subOsc.disconnect(); } catch { /* ignore */ }
      this.subOsc = null;
    }
  }
}

/**
 * 13. Binaural Delta Waves (3 Hz beat difference)
 * Left: 136.1 Hz, Right: 139.1 Hz for deep REM sleep
 */
export class BinauralDeltaGenerator extends BaseProceduralGenerator {
  private oscL: OscillatorNode | null = null;
  private oscR: OscillatorNode | null = null;
  private merger: ChannelMergerNode | null = null;

  public startSynthesis(): void {
    const now = this.ctx.currentTime;

    this.oscL = this.ctx.createOscillator();
    this.oscR = this.ctx.createOscillator();

    this.oscL.type = 'sine';
    this.oscR.type = 'sine';

    this.oscL.frequency.setValueAtTime(136.1, now);
    this.oscR.frequency.setValueAtTime(139.1, now); // 3 Hz difference (Delta)

    const gainL = this.ctx.createGain();
    const gainR = this.ctx.createGain();
    gainL.gain.setValueAtTime(0.4, now);
    gainR.gain.setValueAtTime(0.4, now);

    this.merger = this.ctx.createChannelMerger(2);

    this.oscL.connect(gainL);
    this.oscR.connect(gainR);

    gainL.connect(this.merger, 0, 0);
    gainR.connect(this.merger, 0, 1);

    this.merger.connect(this.outputGain);

    this.oscL.start();
    this.oscR.start();
  }

  public stopSynthesis(): void {
    if (this.oscL) {
      try { this.oscL.stop(); this.oscL.disconnect(); } catch { /* ignore */ }
      this.oscL = null;
    }
    if (this.oscR) {
      try { this.oscR.stop(); this.oscR.disconnect(); } catch { /* ignore */ }
      this.oscR = null;
    }
  }
}

/**
 * 14. Mechanical Train: Rhythmic wheel-rail track impacts ("clack-clack") + carriage rumble
 */
export class MechanicalTrainGenerator extends BaseProceduralGenerator {
  private rumbleSource: AudioBufferSourceNode | null = null;
  private trainTimer: number | null = null;

  public startSynthesis(): void {
    // 1. Continuous train car low vibration
    const sr = this.ctx.sampleRate;
    const frames = sr * 4;
    const buffer = this.ctx.createBuffer(2, frames, sr);
    const l = buffer.getChannelData(0);
    const r = buffer.getChannelData(1);

    let lastL = 0, lastR = 0;
    for (let i = 0; i < frames; i++) {
      lastL = (lastL + 0.04 * (Math.random() * 2 - 1)) / 1.04;
      lastR = (lastR + 0.04 * (Math.random() * 2 - 1)) / 1.04;
      l[i] = lastL * 2.5;
      r[i] = lastR * 2.5;
    }

    const lp = this.ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.setValueAtTime(160, this.ctx.currentTime);

    this.rumbleSource = this.ctx.createBufferSource();
    this.rumbleSource.buffer = buffer;
    this.rumbleSource.loop = true;
    this.rumbleSource.connect(lp);
    lp.connect(this.outputGain);
    this.rumbleSource.start();

    // 2. Rhythmic track joints (Clack-clack) every 1.4 seconds
    this.scheduleTrainBeat();
  }

  private scheduleTrainBeat(): void {
    if (!this.running) return;

    // Dual impact: primary click, then secondary trailing bogie click
    this.triggerRailClack(0.0);
    this.triggerRailClack(0.14);
    this.triggerRailClack(0.48);
    this.triggerRailClack(0.62);

    this.trainTimer = window.setTimeout(() => this.scheduleTrainBeat(), 1450);
  }

  private triggerRailClack(delaySeconds: number): void {
    const now = this.ctx.currentTime + delaySeconds;
    const duration = 0.05;

    const osc = this.ctx.createOscillator();
    const filter = this.ctx.createBiquadFilter();
    const gain = this.ctx.createGain();

    osc.type = 'triangle';
    osc.frequency.setValueAtTime(280 + Math.random() * 60, now);
    osc.frequency.exponentialRampToValueAtTime(70, now + duration);

    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(650, now);
    filter.Q.setValueAtTime(2.2, now);

    gain.gain.setValueAtTime(0.28, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);

    osc.connect(filter);
    filter.connect(gain);
    gain.connect(this.outputGain);

    osc.start(now);
    osc.stop(now + duration);
  }

  public stopSynthesis(): void {
    if (this.trainTimer) {
      clearTimeout(this.trainTimer);
      this.trainTimer = null;
    }
    if (this.rumbleSource) {
      try {
        this.rumbleSource.stop();
        this.rumbleSource.disconnect();
      } catch {
        // ignore
      }
      this.rumbleSource = null;
    }
  }
}

/**
 * 15. Clock Ticking: Minimalist precision tick-tock at 60 BPM (1.0 Hz)
 */
export class ClockTickingGenerator extends BaseProceduralGenerator {
  private clockTimer: number | null = null;
  private isTick: boolean = true;

  public startSynthesis(): void {
    this.scheduleTick();
  }

  private scheduleTick(): void {
    if (!this.running) return;

    const now = this.ctx.currentTime;
    const duration = 0.022;

    const osc = this.ctx.createOscillator();
    const filter = this.ctx.createBiquadFilter();
    const gain = this.ctx.createGain();

    osc.type = 'sine';
    // Alternating Tick (higher 1180 Hz) and Tock (lower 880 Hz)
    const baseFreq = this.isTick ? 1220 : 880;
    this.isTick = !this.isTick;

    osc.frequency.setValueAtTime(baseFreq, now);
    osc.frequency.exponentialRampToValueAtTime(220, now + duration);

    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(baseFreq, now);
    filter.Q.setValueAtTime(4.0, now);

    gain.gain.setValueAtTime(0.22, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);

    osc.connect(filter);
    filter.connect(gain);
    gain.connect(this.outputGain);

    osc.start(now);
    osc.stop(now + duration);

    this.clockTimer = window.setTimeout(() => this.scheduleTick(), 1000);
  }

  public stopSynthesis(): void {
    if (this.clockTimer) {
      clearTimeout(this.clockTimer);
      this.clockTimer = null;
    }
  }
}
