import { BaseProceduralGenerator } from '../SoundGenerator';

/**
 * 5. Heavy Rain Generator: Continuous stochastic drops + low ambient shower bed
 */
export class HeavyRainGenerator extends BaseProceduralGenerator {
  private bedSource: AudioBufferSourceNode | null = null;
  private dropIntervalTimer: number | null = null;

  public startSynthesis(): void {
    // 1. Continuous rain bed
    const sampleRate = this.ctx.sampleRate;
    const bedDuration = 5;
    const bedFrames = sampleRate * bedDuration;
    const bedBuffer = this.ctx.createBuffer(2, bedFrames, sampleRate);
    const bedL = bedBuffer.getChannelData(0);
    const bedR = bedBuffer.getChannelData(1);

    let b0L = 0, b1L = 0;
    let b0R = 0, b1R = 0;
    for (let i = 0; i < bedFrames; i++) {
      const wL = Math.random() * 2 - 1;
      const wR = Math.random() * 2 - 1;
      b0L = 0.9 * b0L + wL * 0.1;
      b1L = 0.85 * b1L + b0L * 0.15;
      b0R = 0.9 * b0R + wR * 0.1;
      b1R = 0.85 * b1R + b0R * 0.15;
      bedL[i] = b1L * 0.35;
      bedR[i] = b1R * 0.35;
    }

    const bedFilter = this.ctx.createBiquadFilter();
    bedFilter.type = 'lowpass';
    bedFilter.frequency.setValueAtTime(2400, this.ctx.currentTime);

    this.bedSource = this.ctx.createBufferSource();
    this.bedSource.buffer = bedBuffer;
    this.bedSource.loop = true;
    this.bedSource.connect(bedFilter);
    bedFilter.connect(this.outputGain);
    this.bedSource.start();

    // 2. Stochastic raindrop impacts
    this.scheduleDrops();
  }

  private scheduleDrops(): void {
    if (!this.running) return;

    // Trigger 1-3 drops in quick succession
    const dropCount = Math.floor(Math.random() * 3) + 1;
    for (let i = 0; i < dropCount; i++) {
      const dropDelay = Math.random() * 60;
      setTimeout(() => {
        if (!this.running) return;
        this.triggerSingleDrop();
      }, dropDelay);
    }

    const nextBatchDelay = 50 + Math.random() * 70;
    this.dropIntervalTimer = window.setTimeout(() => this.scheduleDrops(), nextBatchDelay);
  }

  private triggerSingleDrop(): void {
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const pan = this.ctx.createStereoPanner();

    const startFreq = 2200 + Math.random() * 1800;
    const endFreq = 400 + Math.random() * 400;
    const duration = 0.03 + Math.random() * 0.04;
    const now = this.ctx.currentTime;

    osc.type = 'sine';
    osc.frequency.setValueAtTime(startFreq, now);
    osc.frequency.exponentialRampToValueAtTime(endFreq, now + duration);

    gain.gain.setValueAtTime(0.08 * (Math.random() * 0.5 + 0.5), now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);

    pan.pan.setValueAtTime(Math.random() * 1.6 - 0.8, now);

    osc.connect(gain);
    gain.connect(pan);
    pan.connect(this.outputGain);

    osc.start(now);
    osc.stop(now + duration);
  }

  public stopSynthesis(): void {
    if (this.dropIntervalTimer) {
      clearTimeout(this.dropIntervalTimer);
      this.dropIntervalTimer = null;
    }
    if (this.bedSource) {
      try {
        this.bedSource.stop();
        this.bedSource.disconnect();
      } catch {
        // ignore
      }
      this.bedSource = null;
    }
  }
}

/**
 * 6. Distant Thunder Generator: Deep resonant sub-bass bursts with rolling echoes
 */
export class DistantThunderGenerator extends BaseProceduralGenerator {
  private thunderTimer: number | null = null;
  private noiseBuffer: AudioBuffer | null = null;

  public startSynthesis(): void {
    // Pre-create 6-second low-frequency noise buffer
    const sr = this.ctx.sampleRate;
    const frames = sr * 6;
    this.noiseBuffer = this.ctx.createBuffer(2, frames, sr);
    const l = this.noiseBuffer.getChannelData(0);
    const r = this.noiseBuffer.getChannelData(1);

    let lastL = 0;
    let lastR = 0;
    for (let i = 0; i < frames; i++) {
      lastL = (lastL + 0.02 * (Math.random() * 2 - 1)) / 1.02;
      lastR = (lastR + 0.02 * (Math.random() * 2 - 1)) / 1.02;
      l[i] = lastL;
      r[i] = lastR;
    }

    // Trigger initial thunder shortly after start, then loop
    setTimeout(() => {
      if (this.running) this.triggerThunder();
    }, 1200);

    this.scheduleNextThunder();
  }

  private scheduleNextThunder(): void {
    if (!this.running) return;
    // Repeat every 14 - 28 seconds
    const delay = 14000 + Math.random() * 14000;
    this.thunderTimer = window.setTimeout(() => {
      if (!this.running) return;
      this.triggerThunder();
      this.scheduleNextThunder();
    }, delay);
  }

  private triggerThunder(): void {
    if (!this.noiseBuffer) return;
    const now = this.ctx.currentTime;
    const thunderDuration = 5.5 + Math.random() * 2.5;

    // Sub-bass resonance rumble
    const osc = this.ctx.createOscillator();
    const oscGain = this.ctx.createGain();
    const startPitch = 55 + Math.random() * 20;

    osc.type = 'triangle';
    osc.frequency.setValueAtTime(startPitch, now);
    osc.frequency.exponentialRampToValueAtTime(32, now + 1.8);

    oscGain.gain.setValueAtTime(0.0001, now);
    oscGain.gain.linearRampToValueAtTime(0.45, now + 0.4);
    oscGain.gain.exponentialRampToValueAtTime(0.0001, now + thunderDuration);

    osc.connect(oscGain);
    oscGain.connect(this.outputGain);
    osc.start(now);
    osc.stop(now + thunderDuration);

    // Filtered noise tail
    const noiseSource = this.ctx.createBufferSource();
    noiseSource.buffer = this.noiseBuffer;

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(140, now);
    filter.frequency.linearRampToValueAtTime(70, now + thunderDuration);

    const noiseGain = this.ctx.createGain();
    noiseGain.gain.setValueAtTime(0.0001, now);
    noiseGain.gain.linearRampToValueAtTime(0.6, now + 0.6);
    noiseGain.gain.exponentialRampToValueAtTime(0.0001, now + thunderDuration);

    const pan = this.ctx.createStereoPanner();
    pan.pan.setValueAtTime(Math.random() * 1.4 - 0.7, now);

    noiseSource.connect(filter);
    filter.connect(noiseGain);
    noiseGain.connect(pan);
    pan.connect(this.outputGain);

    noiseSource.start(now);
    noiseSource.stop(now + thunderDuration);
  }

  public stopSynthesis(): void {
    if (this.thunderTimer) {
      clearTimeout(this.thunderTimer);
      this.thunderTimer = null;
    }
  }
}

/**
 * 7. Ocean Waves Generator: Dual LFO filter sweep over deep Brownian/Pink sea noise
 */
export class OceanWavesGenerator extends BaseProceduralGenerator {
  private noiseSource: AudioBufferSourceNode | null = null;
  private lfo1: OscillatorNode | null = null;
  private lfo2: OscillatorNode | null = null;

  public startSynthesis(): void {
    const sr = this.ctx.sampleRate;
    const seconds = 8;
    const frames = sr * seconds;
    const buffer = this.ctx.createBuffer(2, frames, sr);
    const l = buffer.getChannelData(0);
    const r = buffer.getChannelData(1);

    let lastL = 0, lastR = 0;
    for (let i = 0; i < frames; i++) {
      lastL = (lastL + 0.03 * (Math.random() * 2 - 1)) / 1.03;
      lastR = (lastR + 0.03 * (Math.random() * 2 - 1)) / 1.03;
      l[i] = lastL * 3.2;
      r[i] = lastR * 3.2;
    }

    this.noiseSource = this.ctx.createBufferSource();
    this.noiseSource.buffer = buffer;
    this.noiseSource.loop = true;

    // Resonant lowpass filter swept by LFO
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(320, this.ctx.currentTime);
    filter.Q.setValueAtTime(2.5, this.ctx.currentTime);

    // LFO 1: Swell & Crest frequency modulation (~0.08 Hz = ~12.5s tidal cycle)
    this.lfo1 = this.ctx.createOscillator();
    this.lfo1.type = 'sine';
    this.lfo1.frequency.setValueAtTime(0.08, this.ctx.currentTime);

    const lfoGain = this.ctx.createGain();
    lfoGain.gain.setValueAtTime(260, this.ctx.currentTime);
    this.lfo1.connect(lfoGain);
    lfoGain.connect(filter.frequency);

    // LFO 2: Volume dynamics swell
    this.lfo2 = this.ctx.createOscillator();
    this.lfo2.type = 'sine';
    this.lfo2.frequency.setValueAtTime(0.08, this.ctx.currentTime);

    const waveAmpGain = this.ctx.createGain();
    waveAmpGain.gain.setValueAtTime(0.45, this.ctx.currentTime);
    this.lfo2.connect(waveAmpGain.gain);

    this.noiseSource.connect(filter);
    filter.connect(waveAmpGain);
    waveAmpGain.connect(this.outputGain);

    this.noiseSource.start();
    this.lfo1.start();
    this.lfo2.start();
  }

  public stopSynthesis(): void {
    if (this.noiseSource) {
      try {
        this.noiseSource.stop();
        this.noiseSource.disconnect();
      } catch {
        // ignore
      }
      this.noiseSource = null;
    }
    if (this.lfo1) {
      try {
        this.lfo1.stop();
        this.lfo1.disconnect();
      } catch {
        // ignore
      }
      this.lfo1 = null;
    }
    if (this.lfo2) {
      try {
        this.lfo2.stop();
        this.lfo2.disconnect();
      } catch {
        // ignore
      }
      this.lfo2 = null;
    }
  }
}

/**
 * 8. Cozy Fireplace Generator: Random high-frequency wood crackles + warm low rumble
 */
export class CozyFireplaceGenerator extends BaseProceduralGenerator {
  private bedSource: AudioBufferSourceNode | null = null;
  private crackleTimer: number | null = null;

  public startSynthesis(): void {
    // 1. Warm bed rumble
    const sr = this.ctx.sampleRate;
    const frames = sr * 4;
    const buffer = this.ctx.createBuffer(2, frames, sr);
    const l = buffer.getChannelData(0);
    const r = buffer.getChannelData(1);

    let lastL = 0, lastR = 0;
    for (let i = 0; i < frames; i++) {
      lastL = (lastL + 0.015 * (Math.random() * 2 - 1)) / 1.015;
      lastR = (lastR + 0.015 * (Math.random() * 2 - 1)) / 1.015;
      l[i] = lastL * 2.8;
      r[i] = lastR * 2.8;
    }

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(380, this.ctx.currentTime);

    this.bedSource = this.ctx.createBufferSource();
    this.bedSource.buffer = buffer;
    this.bedSource.loop = true;
    this.bedSource.connect(filter);
    filter.connect(this.outputGain);
    this.bedSource.start();

    // 2. Crackling pops
    this.scheduleCrackles();
  }

  private scheduleCrackles(): void {
    if (!this.running) return;

    // Burst of 1-4 crackle snaps
    const snaps = Math.floor(Math.random() * 4) + 1;
    for (let i = 0; i < snaps; i++) {
      const delay = Math.random() * 120;
      setTimeout(() => {
        if (this.running) this.triggerCrackle();
      }, delay);
    }

    const nextBatch = 70 + Math.random() * 180;
    this.crackleTimer = window.setTimeout(() => this.scheduleCrackles(), nextBatch);
  }

  private triggerCrackle(): void {
    const now = this.ctx.currentTime;
    const duration = 0.008 + Math.random() * 0.018;

    // High frequency snappy burst
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const pan = this.ctx.createStereoPanner();

    const isDeepPop = Math.random() < 0.25;
    const baseFreq = isDeepPop ? 300 + Math.random() * 250 : 2500 + Math.random() * 2800;

    osc.type = isDeepPop ? 'triangle' : 'sine';
    osc.frequency.setValueAtTime(baseFreq, now);
    osc.frequency.exponentialRampToValueAtTime(100, now + duration);

    const amp = isDeepPop ? 0.35 : 0.15 * (Math.random() * 0.7 + 0.3);
    gain.gain.setValueAtTime(amp, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);

    pan.pan.setValueAtTime(Math.random() * 1.6 - 0.8, now);

    osc.connect(gain);
    gain.connect(pan);
    pan.connect(this.outputGain);

    osc.start(now);
    osc.stop(now + duration);
  }

  public stopSynthesis(): void {
    if (this.crackleTimer) {
      clearTimeout(this.crackleTimer);
      this.crackleTimer = null;
    }
    if (this.bedSource) {
      try {
        this.bedSource.stop();
        this.bedSource.disconnect();
      } catch {
        // ignore
      }
      this.bedSource = null;
    }
  }
}

/**
 * 9. Forest Wind Generator: Dual sweeping resonant bandpass filters across pink noise
 */
export class ForestWindGenerator extends BaseProceduralGenerator {
  private noiseSource: AudioBufferSourceNode | null = null;
  private lfo: OscillatorNode | null = null;

  public startSynthesis(): void {
    const sr = this.ctx.sampleRate;
    const frames = sr * 6;
    const buffer = this.ctx.createBuffer(2, frames, sr);
    const l = buffer.getChannelData(0);
    const r = buffer.getChannelData(1);

    let b0L = 0, b1L = 0;
    let b0R = 0, b1R = 0;
    for (let i = 0; i < frames; i++) {
      const wL = Math.random() * 2 - 1;
      const wR = Math.random() * 2 - 1;
      b0L = 0.96 * b0L + wL * 0.08;
      b1L = 0.94 * b1L + b0L * 0.12;
      b0R = 0.96 * b0R + wR * 0.08;
      b1R = 0.94 * b1R + b0R * 0.12;
      l[i] = b1L * 1.8;
      r[i] = b1R * 1.8;
    }

    this.noiseSource = this.ctx.createBufferSource();
    this.noiseSource.buffer = buffer;
    this.noiseSource.loop = true;

    const bpFilter = this.ctx.createBiquadFilter();
    bpFilter.type = 'bandpass';
    bpFilter.frequency.setValueAtTime(450, this.ctx.currentTime);
    bpFilter.Q.setValueAtTime(3.8, this.ctx.currentTime);

    this.lfo = this.ctx.createOscillator();
    this.lfo.type = 'sine';
    this.lfo.frequency.setValueAtTime(0.18, this.ctx.currentTime); // gentle gust cycle

    const lfoGain = this.ctx.createGain();
    lfoGain.gain.setValueAtTime(300, this.ctx.currentTime);
    this.lfo.connect(lfoGain);
    lfoGain.connect(bpFilter.frequency);

    this.noiseSource.connect(bpFilter);
    bpFilter.connect(this.outputGain);

    this.noiseSource.start();
    this.lfo.start();
  }

  public stopSynthesis(): void {
    if (this.noiseSource) {
      try {
        this.noiseSource.stop();
        this.noiseSource.disconnect();
      } catch {
        // ignore
      }
      this.noiseSource = null;
    }
    if (this.lfo) {
      try {
        this.lfo.stop();
        this.lfo.disconnect();
      } catch {
        // ignore
      }
      this.lfo = null;
    }
  }
}

/**
 * 10. Night Crickets Generator: 4.7 kHz pulse-modulated insect chirp patterns
 */
export class NightCricketsGenerator extends BaseProceduralGenerator {
  private cricketTimer: number | null = null;

  public startSynthesis(): void {
    this.schedulePhrase();
  }

  private schedulePhrase(): void {
    if (!this.running) return;

    // Pattern of 3 to 5 rapid chirps
    const count = 3 + Math.floor(Math.random() * 3);
    for (let i = 0; i < count; i++) {
      const delay = i * 110;
      setTimeout(() => {
        if (this.running) this.triggerSingleChirp();
      }, delay);
    }

    // Silence between chirp phrases
    const nextPhrase = count * 110 + 600 + Math.random() * 1200;
    this.cricketTimer = window.setTimeout(() => this.schedulePhrase(), nextPhrase);
  }

  private triggerSingleChirp(): void {
    const now = this.ctx.currentTime;
    const chirpDuration = 0.06;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const pan = this.ctx.createStereoPanner();

    osc.type = 'sine';
    const pitch = 4650 + Math.random() * 200;
    osc.frequency.setValueAtTime(pitch, now);

    // AM modulation for wing flutter
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.linearRampToValueAtTime(0.12, now + 0.015);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + chirpDuration);

    pan.pan.setValueAtTime(Math.random() * 1.4 - 0.7, now);

    osc.connect(gain);
    gain.connect(pan);
    pan.connect(this.outputGain);

    osc.start(now);
    osc.stop(now + chirpDuration);
  }

  public stopSynthesis(): void {
    if (this.cricketTimer) {
      clearTimeout(this.cricketTimer);
      this.cricketTimer = null;
    }
  }
}

/**
 * 11. Mountain Stream Generator: Gargling water noise + downward sweeping bubble chirps
 */
export class MountainStreamGenerator extends BaseProceduralGenerator {
  private bedSource: AudioBufferSourceNode | null = null;
  private bubbleTimer: number | null = null;

  public startSynthesis(): void {
    // 1. Water bed noise through resonant bandpass
    const sr = this.ctx.sampleRate;
    const frames = sr * 5;
    const buffer = this.ctx.createBuffer(2, frames, sr);
    const l = buffer.getChannelData(0);
    const r = buffer.getChannelData(1);

    for (let i = 0; i < frames; i++) {
      l[i] = (Math.random() * 2 - 1) * 0.2;
      r[i] = (Math.random() * 2 - 1) * 0.2;
    }

    const bp = this.ctx.createBiquadFilter();
    bp.type = 'bandpass';
    bp.frequency.setValueAtTime(780, this.ctx.currentTime);
    bp.Q.setValueAtTime(1.8, this.ctx.currentTime);

    this.bedSource = this.ctx.createBufferSource();
    this.bedSource.buffer = buffer;
    this.bedSource.loop = true;
    this.bedSource.connect(bp);
    bp.connect(this.outputGain);
    this.bedSource.start();

    // 2. Continuous bubbling drops
    this.scheduleBubbles();
  }

  private scheduleBubbles(): void {
    if (!this.running) return;

    this.triggerBubble();

    const nextBubble = 35 + Math.random() * 80;
    this.bubbleTimer = window.setTimeout(() => this.scheduleBubbles(), nextBubble);
  }

  private triggerBubble(): void {
    const now = this.ctx.currentTime;
    const duration = 0.04 + Math.random() * 0.05;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const pan = this.ctx.createStereoPanner();

    const fStart = 900 + Math.random() * 700;
    const fEnd = 450 + Math.random() * 300;

    osc.type = 'sine';
    osc.frequency.setValueAtTime(fStart, now);
    osc.frequency.exponentialRampToValueAtTime(fEnd, now + duration);

    gain.gain.setValueAtTime(0.06 * (Math.random() * 0.5 + 0.5), now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);

    pan.pan.setValueAtTime(Math.random() * 1.6 - 0.8, now);

    osc.connect(gain);
    gain.connect(pan);
    pan.connect(this.outputGain);

    osc.start(now);
    osc.stop(now + duration);
  }

  public stopSynthesis(): void {
    if (this.bubbleTimer) {
      clearTimeout(this.bubbleTimer);
      this.bubbleTimer = null;
    }
    if (this.bedSource) {
      try {
        this.bedSource.stop();
        this.bedSource.disconnect();
      } catch {
        // ignore
      }
      this.bedSource = null;
    }
  }
}
